cards.state_display:
[[[
  const a = entity.attributes.last_completed_cycle || {};
  const v = a.total_km;
  if (v === undefined || v === null || isNaN(v)) return '—';
  return Number(v).toLocaleString('fr-FR', {minimumFractionDigits: 1, maximumFractionDigits: 1}) + ' km';
]]]

