[[[
  const a = entity.attributes.last_completed_cycle || {};
  if (a.total_cost === undefined || a.total_cost === null) return '—';
  const n = v => Number(v).toLocaleString('fr-FR', {minimumFractionDigits: 2, maximumFractionDigits: 2});
  return n(a.total_cost) + ' € · ' + n(a.total_eur_100km) + ' €/100 km';
]]]

